-- Isolated PostgreSQL fixture for device RPC epoch fencing. CI-only.
\set ON_ERROR_STOP on
DO $$ BEGIN CREATE ROLE anon; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE supabase_admin; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.user_id',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
GRANT USAGE ON SCHEMA auth TO anon;
GRANT EXECUTE ON FUNCTION auth.jwt() TO anon;
CREATE TYPE public.device_type AS ENUM ('display','host','buzzer');
CREATE TYPE public.game_team AS ENUM ('A','B');
CREATE TABLE public.games(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES auth.users(id));
CREATE TABLE public.control_runtime_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_id uuid NOT NULL REFERENCES public.games(id),owner_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz DEFAULT now(),last_activity_at timestamptz DEFAULT now(),expires_at timestamptz DEFAULT now()+interval '1 hour',ended_at timestamptz,end_reason text);
CREATE TABLE public.control_device_link_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.control_runtime_sessions(id),game_id uuid NOT NULL REFERENCES public.games(id),device_type text NOT NULL,token uuid NOT NULL UNIQUE);
CREATE TABLE public.control_device_shares(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.control_runtime_sessions(id),game_id uuid NOT NULL REFERENCES public.games(id),device_type text NOT NULL,token uuid NOT NULL UNIQUE,revoked_at timestamptz);
CREATE FUNCTION public.control_device_key_valid(p_game_id uuid,p_device_type text,p_key text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM public.control_device_link_tokens WHERE game_id=p_game_id AND device_type=p_device_type AND token::text=p_key) $$;
CREATE TABLE public.game_state(game_id uuid PRIMARY KEY,step text,detail jsonb,rev bigint,updated_at timestamptz,locked_until timestamptz);
CREATE TABLE public.game_state_display_completion(game_id uuid PRIMARY KEY,rendered_rev bigint,requested_rev bigint);
CREATE PUBLICATION supabase_realtime FOR TABLE public.game_state;
CREATE TABLE public.display_audio_unlock(game_id uuid PRIMARY KEY,session_nonce text,request_nonce text,acknowledged_nonce text,requested_at timestamptz,acknowledged_at timestamptz);
CREATE TABLE public.game_sessions(id uuid PRIMARY KEY,game_id uuid,control_version integer,ended_at timestamptz);
CREATE TABLE public.game_session_active(game_id uuid,session_id uuid);
CREATE TABLE public.control2_device_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,game_id uuid,session_id uuid,event_type text,event_id text,details jsonb,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX control2_device_events_event_id_idx ON public.control2_device_events(game_id,event_id) WHERE event_id IS NOT NULL;
CREATE FUNCTION public.control_runtime_session_touch(p_game_id uuid,p_session_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
CREATE FUNCTION public.game_state_get(uuid,public.device_type,text) RETURNS public.game_state LANGUAGE sql AS $$ SELECT NULL::public.game_state $$;
CREATE FUNCTION public.game_state_buzzer_press(uuid,text,public.game_team) RETURNS public.game_state LANGUAGE sql AS $$ SELECT NULL::public.game_state $$;
CREATE FUNCTION public.game_state_display_complete(uuid,text,bigint) RETURNS void LANGUAGE sql AS $$ SELECT $$;
CREATE FUNCTION public.game_state_display_is_ready(uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public.begin_display_audio_session(uuid,text,text) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public.acknowledge_display_audio_unlock(uuid,text,text) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public.control2_display_event(uuid,text,jsonb) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;

\ir ../../supabase/migrations/2026-10-15_371_control2_device_leases.sql
\ir ../../supabase/migrations/2026-10-15_372_control2_device_lease_fencing.sql
\ir ../../supabase/migrations/2026-10-15_373_legacy_buzzer_ready_compat.sql
\ir ../../supabase/migrations/2026-10-15_374_restore_buzzer_guards.sql
\ir ../../supabase/migrations/2026-10-15_375_control2_realtime_device_auth.sql
ALTER TABLE public.game_state_display_completion ENABLE ROW LEVEL SECURITY;
\ir ../../supabase/migrations/2026-10-15_376_control2_display_completion_realtime.sql
\ir ../../supabase/migrations/2026-10-15_377_control2_display_ack_in_game_state.sql
\ir ../../supabase/migrations/2026-10-15_378_control2_device_progress_telemetry.sql

CREATE FUNCTION pg_temp.assert_true(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Assertion: %',message; END IF; END $$;

INSERT INTO auth.users VALUES('00000000-0000-0000-0000-000000000001');
INSERT INTO public.games VALUES
 ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),
 ('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000001');
INSERT INTO public.control_runtime_sessions(id,game_id,owner_id,device_protocol) VALUES
 ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',2);
INSERT INTO public.control_runtime_sessions(id,game_id,owner_id,device_protocol) VALUES
 ('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000001',1);
INSERT INTO public.control_device_link_tokens(session_id,game_id,device_type,token) VALUES
 ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001'),
 ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','buzzer','30000000-0000-0000-0000-000000000004'),
 ('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','display','30000000-0000-0000-0000-000000000002'),
 ('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','buzzer','30000000-0000-0000-0000-000000000003');
INSERT INTO public.game_state(game_id,step,detail,rev,updated_at) VALUES
 ('10000000-0000-0000-0000-000000000001','setup', '{}'::jsonb,1,now()),
 ('10000000-0000-0000-0000-000000000002','setup', '{}'::jsonb,1,now());
INSERT INTO public.game_state_display_completion(game_id,rendered_rev,requested_rev) VALUES
 ('10000000-0000-0000-0000-000000000001',1,1),
 ('10000000-0000-0000-0000-000000000002',1,2);
SELECT set_config('test.user_id','00000000-0000-0000-0000-000000000001',false);
SELECT pg_temp.assert_true((control_device_instance_register('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001')->>'epoch')='1','first display receives epoch 1');
SELECT control_device_instance_heartbeat('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,'{"received_rev":12,"rendered_rev":11,"started_sound_cue_seq":4}'::jsonb);
SELECT pg_temp.assert_true((SELECT received_rev=12 AND rendered_rev=11 AND started_sound_cue_seq=4 FROM public.control_device_connections WHERE id='40000000-0000-0000-0000-000000000001'),'fenced heartbeat records per-instance render progress');
SELECT control_device_instance_heartbeat('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,'{"received_rev":2,"rendered_rev":3,"started_sound_cue_seq":1}'::jsonb);
SELECT pg_temp.assert_true((SELECT received_rev=12 AND rendered_rev=11 AND started_sound_cue_seq=4 FROM public.control_device_connections WHERE id='40000000-0000-0000-0000-000000000001'),'reported progress is monotonic across delayed heartbeat payloads');
SELECT pg_temp.assert_true(control_device_realtime_authorize('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1)->>'session_id'='20000000-0000-0000-0000-000000000001','realtime authorization returns scope only for current primary');
SELECT pg_temp.assert_true(control_device_realtime_claim_valid('10000000-0000-0000-0000-000000000001',jsonb_build_object('role','anon','game_id','10000000-0000-0000-0000-000000000001','device_type','display','session_id','20000000-0000-0000-0000-000000000001','connection_id','40000000-0000-0000-0000-000000000001','epoch',1,'exp',extract(epoch FROM now())::bigint+300)),'current primary claims pass RLS validation');
SELECT pg_temp.assert_true(_control_device_action_valid('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1),'current primary epoch authorizes device RPC');
SELECT pg_temp.assert_true(game_state_get('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1) IS DISTINCT FROM NULL::public.game_state,'fenced RPC can read state for current primary');
SELECT game_state_display_complete('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001',1,'40000000-0000-0000-0000-000000000001',1);
SELECT pg_temp.assert_true((SELECT display_rendered_rev=1 FROM public.game_state WHERE game_id='10000000-0000-0000-0000-000000000001'),'display acknowledgment is mirrored into game_state for realtime delivery');
SELECT pg_temp.assert_true(game_state_get('10000000-0000-0000-0000-000000000002','display','30000000-0000-0000-0000-000000000002') IS DISTINCT FROM NULL::public.game_state,'legacy key-only RPC remains available for protocol 1');
SELECT pg_temp.assert_true(NOT game_state_display_is_ready('10000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000003'),'legacy Buzzer can still call ready RPC without device_type');
SELECT pg_temp.assert_true(NOT _control_device_action_valid('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',2),'stale epoch is denied');
SELECT control_device_instance_register('10000000-0000-0000-0000-000000000001','buzzer','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000004');
UPDATE public.game_state SET step='r_duel',detail='{"settings":{"physicalBuzzer":true},"rounds":{"duel":{"lastPressed":null}}}' WHERE game_id='10000000-0000-0000-0000-000000000001';
DO $$ BEGIN
  PERFORM game_state_buzzer_press('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','A','40000000-0000-0000-0000-000000000004',1);
  RAISE EXCEPTION 'expected device_disabled';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'device_disabled' THEN RAISE; END IF;
END $$;
UPDATE public.game_state SET detail='{"settings":{"physicalBuzzer":false},"rounds":{"duel":{"lastPressed":null}}}',locked_until=now()+interval '1 minute' WHERE game_id='10000000-0000-0000-0000-000000000001';
DO $$ BEGIN
  PERFORM game_state_buzzer_press('10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','A','40000000-0000-0000-0000-000000000004',1);
  RAISE EXCEPTION 'expected locked';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'locked' THEN RAISE; END IF;
END $$;
SELECT pg_temp.assert_true(NOT _control_device_action_valid('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001',NULL,NULL),'key-only legacy call is denied for protocol 2');
SELECT pg_temp.assert_true((control_device_instance_register('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002')->>'state')='waiting','second display queues');
SELECT pg_temp.assert_true(NOT control_device_realtime_claim_valid('10000000-0000-0000-0000-000000000001',jsonb_build_object('role','anon','game_id','10000000-0000-0000-0000-000000000001','device_type','display','session_id','20000000-0000-0000-0000-000000000001','connection_id','40000000-0000-0000-0000-000000000002','epoch',1,'exp',extract(epoch FROM now())::bigint+300)),'waiting connection claims fail RLS validation');
SELECT pg_temp.assert_true(NOT _control_device_action_valid('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',NULL),'waiting display cannot access active RPCs');
SELECT pg_temp.assert_true((control_device_instance_release('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1)->>'primary_connection_id')='40000000-0000-0000-0000-000000000002','release promotes next display');
SELECT pg_temp.assert_true(NOT _control_device_action_valid('10000000-0000-0000-0000-000000000001','display','30000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1),'demoted display cannot access active RPCs');
SELECT pg_temp.assert_true(NOT control_device_realtime_claim_valid('10000000-0000-0000-0000-000000000001',jsonb_build_object('role','anon','game_id','10000000-0000-0000-0000-000000000001','device_type','display','session_id','20000000-0000-0000-0000-000000000001','connection_id','40000000-0000-0000-0000-000000000001','epoch',1,'exp',extract(epoch FROM now())::bigint+300)),'demoted connection claims fail RLS validation');
ALTER TABLE public.game_state ENABLE ROW LEVEL SECURITY;
SELECT set_config('request.jwt.claims',jsonb_build_object('role','anon','game_id','10000000-0000-0000-0000-000000000001','device_type','display','session_id','20000000-0000-0000-0000-000000000001','connection_id','40000000-0000-0000-0000-000000000002','epoch',2,'exp',extract(epoch FROM now())::bigint+300)::text,false);
SET ROLE anon;
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.game_state WHERE game_id='10000000-0000-0000-0000-000000000001'),'scoped token sees only authorized game state row');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.game_state WHERE game_id='10000000-0000-0000-0000-000000000002'),'scoped token cannot read a different game');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.game_state_display_completion WHERE game_id='10000000-0000-0000-0000-000000000001'),'scoped primary token can read its game completion row');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.game_state_display_completion WHERE game_id='10000000-0000-0000-0000-000000000002'),'scoped primary token cannot read another game completion');
SELECT set_config('request.jwt.claims','{}',false);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.game_state WHERE game_id='10000000-0000-0000-0000-000000000001'),'ordinary anon token sees no game state row');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.game_state_display_completion WHERE game_id='10000000-0000-0000-0000-000000000001'),'ordinary anon token sees no display completion row');
RESET ROLE;
\echo 'Control2 device lease fencing SQL checks passed'
